//go:build linux

package freshstore

import (
	"encoding/base64"
	"errors"
	"os"
	"path/filepath"
	"reflect"
	"testing"
)

// Claim: exact pinned negative bytes are rejected with the original independent
// manifest identity retained. Parser-reaching cases are tested separately.
func TestFreshFrozenNegativeIdentity(t *testing.T) {
	cases := []struct {
		name          string
		two           bool
		encoded, hash string
	}{
		{"omitted", false, "", "8468b2c8ac5643e8b6ec3903e0637b56d0c3073379a21f2137edca14cd3c4730"},
		{"extra", false, "", "3ef2705e33481d903e1696d805fd20af84e80a011c62eef512c180565900b705"},
		{"duplicate", true, "", "4fbb14e133a7a55449e98a023115e2de3430e8da31176d4f4c584f8025d912bf"},
		{"reordered", true, "", "095453c584e10293599ff5955ffc07d96341e831dc90bbc9d0840af4871f0232"},
		{"raw-length", false, "", "d05b9b1c042442dc94a8c5ad85cb987eb3ab9a4ffe0755c0731df7f9ebbbf2ff"},
		{"encoded-length", false, "", "27a341fab9d078ae7a33369b485f6b9b7a86c9bd6c7738ec9ad2d9eeef50968c"},
		{"encoded-digest", false, "", "a7e8880c4b88343342a872675571d6022dc6cfa3bbf24e6ee1ff6855aa1e37b9"},
		{"raw-digest", false, "", "dbe79e8e786bccac2cff014d58cbddf286943a6e56b9d6a25a2a738d8521f0a7"},
		{"wrong-scope", false, "", "2ae3b920733cbc8ed2cef0a56a52af13578d20d2b0e17e2b295691054fb7f8fe"},
		{"wrong-pin", false, "", "f2e797936496702a0eae0e39eb8f2d9d51c22ab158f6809e96b239b357f49f73"},
		{"missing-prev", false, "", "856f239e147de531f79c041e61d27e95b32d1771e37e300fc61e1cb42f17f309"},
		{"empty-prev", false, "", "ccff9a91c7c94804add82f9a14a0e977aa8187428558b25c7a4c536aa576efa5"},
		{"empty-inventory", false, "", "8468b2c8ac5643e8b6ec3903e0637b56d0c3073379a21f2137edca14cd3c4730"},
		{"trailing-LF", false, "", "749411bdf416d25d92a60550449f43285346761e5af58c49ee1b0e0f9de77f45"},
		{"BOM", false, "", "bad87f160dbff3fee518777214da934201c1f72691534238a7dfa8b8dc1a3835"},
		{"duplicate-key", false, "", "3664e7038d06f06df7de8dbfaf69583573c23ab2af74c6ed3ad1c19d964750e1"},
		{"alternate-number", false, "", "575b9f98135c25941f65a035c63a5f63404f9d8aaf6e890d16099ef0b3687b1c"},
		{"unknown-key", false, "", "3a626407d42c98ec7d5af7b6e172cfe04db585cb7db9e59c6ad399565f4f6450"},
		{"integer-overflow", false, "", "122ec3b4286d2f563fc574896be991122e2ba5af7055edf52161e05d5ce8e88c"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			f := fixture(t, limits())
			in := inputA()
			d := literalManifestADigest
			if c.two {
				in = twoInputs()
				d = literalManifestAbDigest
			}
			s, e := f.f.Retain(binding(), in)
			if e != nil || s.ManifestDigest != d {
				t.Fatal("valid frozen control", e)
			}
			want := expected(s)
			want.ManifestDigest = d
			if _, e = f.f.ReadExact(want); e != nil {
				t.Fatal("valid read", e)
			}
			bad, e := base64.StdEncoding.DecodeString(c.encoded)
			if e != nil || testHash(bad) != c.hash {
				t.Fatal("pinned negative bytes", e)
			}
			if e = os.WriteFile(filepath.Join(f.path, manifestName(d)), bad, 0600); e != nil {
				t.Fatal(e)
			}
			before := state(t, f)
			got, e := f.f.ReadExact(want)
			if !errors.Is(e, ErrInvalid) || got != nil {
				t.Fatal("changed identity accepted", e)
			}
			if !reflect.DeepEqual(before, state(t, f)) {
				t.Fatal("negative read mutated state")
			}
		})
	}
}
